<?php
if(!defined('ABSPATH'))exit;
function bsktv_meta_box(){add_meta_box('bsktv_details','店家資訊','bsktv_meta_render','post','normal','high');}add_action('add_meta_boxes','bsktv_meta_box');
function bsktv_meta_render($post){wp_nonce_field('bsktv_meta_save','bsktv_meta_nonce');$fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_service_mode'=>'消費模式','bsktv_room_fee'=>'包廂費用','bsktv_host_fee'=>'少爺費用','bsktv_head_fee'=>'幹部費用','bsktv_person_fee'=>'人頭費用','bsktv_girl_fee'=>'小姐費用');echo '<div class="bsktv-admin-grid">';foreach($fields as $key=>$label){$v=get_post_meta($post->ID,$key,true);echo '<p><label><strong>'.esc_html($label).'</strong><br><input style="width:100%" type="text" name="'.esc_attr($key).'" value="'.esc_attr($v).'" /></label></p>';}echo '</div><p class="description">消費資訊正文請直接於文章編輯器撰寫；以上欄位只作店家資訊摘要，不進行自動消費試算。</p>';}
function bsktv_meta_save($id){if(!isset($_POST['bsktv_meta_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsktv_meta_nonce'])),'bsktv_meta_save'))return;if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(wp_is_post_revision($id)||!current_user_can('edit_post',$id))return;$fields=array('bsktv_address','bsktv_hours','bsktv_service_mode','bsktv_room_fee','bsktv_host_fee','bsktv_head_fee','bsktv_person_fee','bsktv_girl_fee');foreach($fields as $k){$v=isset($_POST[$k])?sanitize_text_field(wp_unslash($_POST[$k])):'';if($v==='')delete_post_meta($id,$k);else update_post_meta($id,$k,$v);}}
add_action('save_post_post','bsktv_meta_save');
function bsktv_meta($key,$id=null){return get_post_meta($id?:get_the_ID(),$key,true);}function bsktv_views($id=null){return (int)get_post_meta($id?:get_the_ID(),'bsktv_views',true);}function bsktv_is_featured($id=null){return get_post_meta($id?:get_the_ID(),'bsktv_featured',true)==='1';}function bsktv_is_home_featured($id=null){return get_post_meta($id?:get_the_ID(),'bsktv_home_featured',true)==='1';}
